  'diag.tooltip.MODEL_DISCONNECTED_NODE': 'Nó isolado sem conexão a nenhuma barra — remover ou conectar',
  'diag.tooltip.MODEL_DOUBLE_HINGE': 'Frame com articulação em ambas extremidades não transmite momento — mecanismo se não houver apoio lateral',
  'diag.tooltip.MODEL_DUPLICATE_ELEMENT': 'Duas barras entre os mesmos nós — remover a duplicada',
  'diag.tooltip.MODEL_EMPTY_CASE': 'Caso de carga sem cargas atribuídas — pode gerar combinações nulas',
  'diag.tooltip.MODEL_FEW_NODES': 'São necessários pelo menos 2 nós para formar uma estrutura',
  'diag.tooltip.MODEL_LOAD_ORPHAN_ELEM': 'Carga em barra que já não existe — remover a carga',
  'diag.tooltip.MODEL_LOAD_ORPHAN_NODE': 'Carga em nó que já não existe — remover a carga',
