  'footing.ui.matPunchingMoment.NEGLIGIBLE': 'Momento não equilibrado na ligação Msc = {msc} kN·m (componentes {x} e {y}), abaixo do limiar de significância de {threshold} kN·m: governa o cortante direto. Não é uma verificação do artigo 8.4.4.2.',
