  'loadPlan.warning.addedOnTopOfExisting': 'O plano SOMA-SE a {count} caso(s) existente(s) ({cases}) em vez de substituí-los, portanto as suas cargas serão contadas duas vezes. Marque "substituir cargas existentes" para regerar do zero.',
  'loads.cirsoc101.exception1.applied': 'Exceção 1 aplicada: Lo = {lo} kN/m² ≤ 5 kN/m² e não há áreas de garagem nem de reunião pública.',
  'loads.cirsoc101.exception1.blockedByAssembly': 'Exceção 1 não aplicável: o projeto inclui áreas de garagem ou de reunião pública.',
