  'loads.cirsoc101.note.fSameFactorAsD': 'F é incluído com o mesmo fator de carga que D.',
  'loads.cirsoc101.note.hAdds': 'H soma-se ao efeito da carga variável primária: fator 1,6.',
  'loads.cirsoc101.note.hUnknownAdding': 'O sentido de H não está indicado no projeto, portanto ambos os casos são gerados. Este é o caso em que H se soma ao efeito variável primário (fator 1,6).',
  'loads.cirsoc101.note.hUnknownOpposing': 'O sentido de H não está indicado no projeto, portanto ambos os casos são gerados. Este é o caso em que H se opõe (fator {factor}).',
  'loads.cirsoc101.note.snowAsFlatRoof': 'S é tomado como carga de neve sobre cobertura plana (Exceção 2).',
