  'solver.mechanismHingedNode': 'Mecanismo no nó {nodeId}: todas as {frames} barras têm articulação nesse nó e {doubleHinged} delas são bi-articuladas (apenas axial). O nó não possui rigidez à flexão nem rigidez transversal suficiente.',
