  'svc.errorInCase': 'Erro no caso "{n}": {err}',
  'svc.errorInCase3d': 'Erro no caso 3D "{n}": {err}',
  'svc.hypostaticDofs': 'Estrutura hipostática: apenas {n} GDL restringidos (mínimo 3 para equilíbrio 2D). É um mecanismo.',
  'svc.hypostaticNoHoriz': 'Estrutura hipostática (mecanismo): sem restrição horizontal em nenhum apoio.',
  'svc.hypostaticNoMoment': 'Estrutura hipostática (mecanismo): as reações de apoio não podem resistir momentos — são paralelas, colineares ou concorrentes. Verifique a disposição dos apoios.',
  'svc.hypostaticNoVert': 'Estrutura hipostática (mecanismo): sem restrição vertical em nenhum apoio.',
  'svc.hypostaticUnstable': 'Estrutura hipostática (mecanismo): as reações de apoio não formam um sistema estaticamente estável. Suas linhas de ação são concorrentes ou paralelas.',
  'svc.loadRefDistMissing': 'Carga distribuída referencia a barra {n} que não existe.',
  'svc.loadRefNodeMissing': 'Carga nodal referencia o nó {n} que não existe.',
  'svc.loadRefPointMissing': 'Carga pontual referencia a barra {n} que não existe.',
  'svc.loadRefThermalMissing': 'Carga térmica referencia a barra {n} que não existe.',
  'svc.mechCollinearHinge': 'Mecanismo no nó {n}: todas as barras ({elems}) são colineares e articuladas nesse nó — sem transferência de momento ou estabilidade lateral.',
  'svc.mechDoubleHinged': 'Mecanismo no nó {n}: todas as barras ({elems}) são articuladas em ambas as extremidades — apenas transmitem força axial, sem rigidez lateral ou de flexão.',
  'svc.mechInsufficientStiffness': 'Mecanismo no nó {n}: todas as {elems} barras são articuladas nesse nó e {dbl} são bi-articuladas — rigidez insuficiente.',
  'svc.model3dSupport': 'Este modelo usa apoios 3D ({n}) que não são compatíveis com análise 2D. Mude para Stabileo 3D para analisá-lo.',
  'svc.model3dZCoords': 'Este modelo tem nós com coordenadas Z (geometria 3D). Mude para Stabileo 3D para analisá-lo.',
  'svc.needCombination': 'Defina pelo menos uma combinação de carga',
