  'svc.zeroLength2dButZ': 'Barra {n} tem comprimento zero em 2D mas seus nós diferem em Z ({dz} m). Este é um modelo 3D — mude para Stabileo 3D para analisá-lo.',
  'svc.zeroLengthElement': 'Barra {n} tem comprimento zero (nós {ni} e {nj} coincidem).',
