  'switch2d.noLoadsWarn': 'Este corte não leva nenhuma carga. O pórtico vai resolver e todos os resultados vão dar zero — o que se lê como uma estrutura segura e não como uma sem carregamento. As cargas que atuam sobre barras que o corte não levou ficam com elas.',
